async function showRepoMaps(){
 try{
  const response=await fetch(REPO_MAPS_URL,{cache:'no-store'});
  if(!response.ok)throw new Error(`Map list request failed (${response.status})`);
  const data=await response.json();
  if(!data||!Array.isArray(data.maps))throw new Error('The map list must contain a "maps" array.');
  REPO_MAPS=data.maps.map((entry,index)=>{
   const file=(typeof entry==='string'?entry:entry&&entry.file)?.trim();
   if(typeof file!=='string'||! /^[\w][\w .()-]*\.json$/i.test(file))
    throw new Error(`Invalid map file entry at position ${index+1}.`);
   return {
    file,
    name:entry&&typeof entry==='object'&&typeof entry.name==='string'?entry.name:file.replace(/\.json$/i,''),
    notes:entry&&Number.isInteger(entry.notes)&&entry.notes>=0?entry.notes:null,
    difficulty:entry&&typeof entry.difficulty==='string'&&entry.difficulty.trim()?entry.difficulty.trim():'Difficulty not set'
   };
  });
  const rows=REPO_MAPS.map((map,index)=>B(`repo:${index}`,`<span>${esc(map.name)}</span><span class="repo-map-meta">${map.notes===null?'Notes not set':`${map.notes} notes`} · ${esc(map.difficulty)}</span>`,0,index===0)).join('');
  show('maps',`<h1>REPO MAP</h1><p>Search and sort maps, then select one for play, preview, or download.</p>${REPO_MAPS.length?`${mapListControls('repo-map-search')}<p id="repo-map-status" aria-live="polite"></p><div class="repo-map-list map-list">${rows}</div>`:'<p>No maps are listed yet.</p>'}${B('main','BACK',1)}`);
  menu.querySelectorAll('.repo-map-list button').forEach((button,index)=>{
   const map=REPO_MAPS[index];
   button.dataset.mapName=map.name.toLocaleLowerCase();
   button.dataset.mapDifficulty=map.difficulty;
   button.dataset.mapNotes=map.notes===null?'':String(map.notes);
  });
  filterRepoMaps();
  const firstRow=menu.querySelector('.repo-map-list button:not([hidden])');
  if(firstRow){
   menu.querySelectorAll('.repo-map-list button').forEach(button=>button.removeAttribute('data-def'));
   firstRow.dataset.def='1';
   fo(firstRow.dataset.a);
  }
 }catch(error){
  const message=location.protocol==='file:'
   ?'Open this game through a local web server to load repository maps. From the game folder, run: python -m http.server'
   :`Could not load ${REPO_MAPS_URL.pathname}: ${error.message}. Check that the file is published at this path.`;
  show('maps',`<h1>REPOSITORY MAPS</h1><p>${esc(message)}</p>${B('main','BACK',1)}`);
 }
}
function showRepoOptions(index){
 const map=REPO_MAPS[index];
 if(!map)return showRepoMaps();
 show('maps',`<h1>${esc(map.name)}</h1><p>${map.notes===null?'Notes not set':`${map.notes} notes`} · ${esc(map.difficulty)}</p>${B('repoPlay','PLAY MAP',0,1)}${B('repoPreview','PREVIEW MAP',1)}${B('repoDownload','DOWNLOAD JSON',1)}${B('repoList','BACK TO REPO MAP',1)}`);
}
function compareMapRows(a,b,sort){
 const [field,direction]=sort.split('-');
 let result;
 if(field==='notes'){
  const aNotes=a.notes===''?null:Number(a.notes),bNotes=b.notes===''?null:Number(b.notes);
  if(aNotes===null||bNotes===null){
   if(aNotes!==bNotes)return aNotes===null?1:-1;
   result=0;
  }else result=(aNotes-bNotes)*(direction==='desc'?-1:1);
 }else{
  const aValue=field==='difficulty'?(a.difficulty||'Not rated'):a.name;
  const bValue=field==='difficulty'?(b.difficulty||'Not rated'):b.name;
  result=aValue.localeCompare(bValue,undefined,{sensitivity:'base'});
  if(direction==='desc')result=-result;
 }
 return result||a.name.localeCompare(b.name,undefined,{sensitivity:'base'});
}
function updateMapList(listSelector,searchId,statusId,total){
 const list=menu.querySelector(listSelector);
 if(!list)return;
 const search=(document.getElementById(searchId)?.value||'').trim().toLocaleLowerCase();
 const sort=MAP_LIST_SORT;
 const rows=Array.from(list.querySelectorAll('button')).map(button=>({
  button,
  name:button.dataset.mapName||'',
  difficulty:button.dataset.mapDifficulty||'',
  notes:button.dataset.mapNotes||''
 })).sort((a,b)=>compareMapRows(a,b,sort));
 let visible=0;
 rows.forEach(row=>{
  const matches=row.name.includes(search);
  row.button.hidden=!matches;
  if(matches)visible++;
  list.appendChild(row.button);
 });
 const status=document.getElementById(statusId);
 if(status)status.textContent=visible?`Showing ${visible} of ${total} maps.`:'No maps match that name.';
}
