function filterCustomMaps(){updateMapList('.custom-map-list','custom-map-search','custom-map-status',menu.querySelectorAll('.custom-map-list button').length)}
async function playRepoMap(index,preview){
 try{
  const entry=REPO_MAPS[index];
  if(!entry)throw new Error('That map is not in the repository list.');
  const response=await fetch(new URL(encodeURIComponent(entry.file),REPO_MAPS_URL),{cache:'no-store'});
  if(!response.ok)throw new Error(`Map request failed (${response.status})`);
  const data=await response.json();
  if(data.format!=='emptylife-map'||!Array.isArray(data.chart)||typeof data.audio!=='string'||!/^data:audio\/[a-z0-9.+-]+;base64,/i.test(data.audio))
   throw new Error('This is not a valid Empty Life map file.');
  if(data.video&& (typeof data.video!=='string'||!/^data:video\/[a-z0-9.+-]+;base64,/i.test(data.video)))
   throw new Error('The map background video must be embedded in the map file.');
  const chart=data.chart.map((note,noteIndex)=>{
   if(!Array.isArray(note)||note.length<7||note.slice(0,7).some(value=>!Number.isFinite(value)))
    throw new Error(`Invalid chart note at position ${noteIndex+1}.`);
   return note.slice(0,8);
  });
  const audioResponse=await fetch(data.audio);
  if(!audioResponse.ok)throw new Error('Could not load the map audio.');
  const audioBlob=await audioResponse.blob();
  if(!audioBlob.size)throw new Error('The map audio file is empty.');
  let videoBlob=null;
  if(data.video){
   const videoResponse=await fetch(data.video);
   if(!videoResponse.ok)throw new Error('Could not load the map background video.');
   videoBlob=await videoResponse.blob();
  }
  const record={name:String(data.name||entry.name),chart,video:videoBlob,videoOn:data.videoOn!==false,remote:true};
  CUST={rec:record,chart:chart.slice().sort((a,b)=>a[0]-b[0]),url:URL.createObjectURL(audioBlob)};
  VIDON=record.videoOn;
  setVid(videoBlob?URL.createObjectURL(videoBlob):null);
  start(preview);
 }catch(error){
  show('maps',`<h1>MAP LOAD FAILED</h1><p>${esc(error.message)}</p>${B('repoMaps','BACK TO MAPS',1,1)}`);
 }
}
async function downloadRepoMap(index){
 try{
  const entry=REPO_MAPS[index];
  if(!entry)throw new Error('That map is not in the repository list.');
  const response=await fetch(new URL(encodeURIComponent(entry.file),REPO_MAPS_URL),{cache:'no-store'});
  if(!response.ok)throw new Error(`Map download failed (${response.status})`);
  const blob=await response.blob();
  const url=URL.createObjectURL(blob),link=document.createElement('a');
  link.href=url;link.download=entry.file;document.body.appendChild(link);link.click();link.remove();
  setTimeout(()=>URL.revokeObjectURL(url),4000);
 }catch(error){
  show('maps',`<h1>DOWNLOAD FAILED</h1><p>${esc(error.message)}</p>${B('repoList','BACK TO REPO MAP',1,1)}`);
 }
}
